package com.fastrag.module.graph.entity;

/**
 * 知识图谱基准测试实体类，对应数据库表 {@code kb_benchmark}。
 *
 * <p>基准测试是知识图谱评测体系的起点，每个基准测试包含一组基于图谱内容生成的测试题目，
 * 用于后续评测任务中验证知识图谱的准确性和完整性。基准测试可以手动创建或通过LLM自动生成。</p>
 *
 * <p>核心字段说明：</p>
 * <ul>
 *   <li>{@code id} - 基准测试唯一标识（雪花算法生成）</li>
 *   <li>{@code kbId} - 所属知识库ID，关联具体知识库</li>
 *   <li>{@code name} - 基准测试名称</li>
 *   <li>{@code description} - 基准测试描述说明</li>
 *   <li>{@code hasGoldChunks} - 是否包含标准检索chunk（0/1），用于评测检索召回率</li>
 *   <li>{@code hasGoldAnswer} - 是否包含标准答案（0/1），用于评测答案准确率</li>
 *   <li>{@code isAutoGenerated} - 是否由LLM自动生成（0/1）</li>
 *   <li>{@code questionCount} - 题目总数</li>
 *   <li>{@code createdAt} - 创建时间</li>
 * </ul>
 *
 * <p>与{@link KbBenchmarkQuestion}为一对多关系，一个基准测试包含多道题目。</p>
 *
 * @see KbBenchmarkQuestion
 */
import com.baomidou.mybatisplus.annotation.IdType;
import com.baomidou.mybatisplus.annotation.TableId;
import com.baomidou.mybatisplus.annotation.TableName;
import lombok.Data;
import java.time.LocalDateTime;
@Data
@TableName("kb_benchmark")
public class KbBenchmark {
    @TableId(type = IdType.ASSIGN_ID) private String id;
    private String kbId, name, description;
    private Integer hasGoldChunks, hasGoldAnswer, isAutoGenerated, questionCount;
    private LocalDateTime createdAt;
}
